INSERT INTO revisions (slug, revision, definition, imported_by, imported_at) VALUES ('demo', 1, '{"title":{"en":"A short tour","zh":"快速导览"},"languages":["en","zh"],"questions":[{"id":"welcome","type":"statement","eyebrow":{"en":"A short tour","zh":"快速导览"},"title":{"en":"Every kind of question, one at a time.","zh":"每一种题型，逐一为您展示。"},"body":{"en":"Swipe left to move on and right to go back. Your progress is kept on this device until you send it.","zh":"向左滑动进入下一题，向右滑动返回上一题。在您提交之前，填写进度会保存在这台设备上。"}},{"id":"name","type":"text","title":{"en":"What should we call you?","zh":"我们该怎么称呼您？"},"required":true,"placeholder":{"en":"Your name","zh":"您的姓名"}},{"id":"email","type":"email","title":{"en":"Where can we reach you?","zh":"我们可以通过哪个邮箱联系您？"},"required":true},{"id":"site","type":"url","title":{"en":"Do you have a website?","zh":"您有网站吗？"}},{"id":"phone","type":"tel","title":{"en":"And a phone number?","zh":"方便留个电话吗？"},"body":{"en":"Only if you would rather talk.","zh":"如果您更愿意电话沟通的话。"}},{"id":"kind","type":"choice","title":{"en":"What brings you here?","zh":"您这次来是为了什么？"},"required":true,"other":true,"options":[{"value":"A new product","label":{"en":"A new product","zh":"开发新产品"}},{"value":"A redesign","label":{"en":"A redesign","zh":"重新设计"}},{"value":"Ongoing support","label":{"en":"Ongoing support","zh":"长期支持"}},{"value":"Just curious","label":{"en":"Just curious","zh":"只是想了解一下"}}]},{"id":"curious","type":"long","title":{"en":"What are you curious about?","zh":"您想了解些什么？"},"showIf":{"id":"kind","equals":"Just curious"}},{"id":"platforms","type":"multi","title":{"en":"Where should it live?","zh":"它需要在哪些平台上使用？"},"body":{"en":"Choose as many as apply.","zh":"可多选。"},"options":[{"value":"Web","label":{"en":"Web","zh":"网页"}},{"value":"iOS","label":{"en":"iOS","zh":"iOS"}},{"value":"Android","label":{"en":"Android","zh":"Android"}},{"value":"Desktop","label":{"en":"Desktop","zh":"桌面端"}}]},{"id":"country","type":"select","title":{"en":"Where are you based?","zh":"您在哪个国家或地区？"},"options":[{"value":"Australia","label":{"en":"Australia","zh":"澳大利亚"}},{"value":"Canada","label":{"en":"Canada","zh":"加拿大"}},{"value":"Germany","label":{"en":"Germany","zh":"德国"}},{"value":"Japan","label":{"en":"Japan","zh":"日本"}},{"value":"Mexico","label":{"en":"Mexico","zh":"墨西哥"}},{"value":"United Kingdom","label":{"en":"United Kingdom","zh":"英国"}},{"value":"United States","label":{"en":"United States","zh":"美国"}},{"value":"Elsewhere","label":{"en":"Elsewhere","zh":"其他地区"}}]},{"id":"existing","type":"boolean","title":{"en":"Is there something already built?","zh":"目前已经有做好的东西了吗？"},"required":true},{"id":"team","type":"number","title":{"en":"How many people are on your team?","zh":"您的团队有多少人？"},"integer":true,"min":1},{"id":"budget","type":"slider","title":{"en":"Roughly, what is the budget?","zh":"预算大概是多少？"},"min":5,"max":100,"step":5,"prefix":"$","suffix":"k","labels":[{"en":"Lean","zh":"精简"},{"en":"Generous","zh":"充裕"}]},{"id":"start","type":"date","title":{"en":"When would you like to begin?","zh":"您希望什么时候开始？"}},{"id":"call","type":"time","title":{"en":"What time suits a call?","zh":"什么时间方便通话？"}},{"id":"priorities","type":"rank","title":{"en":"Put these in order of importance.","zh":"请按重要程度排序。"},"body":{"en":"Tap them from most to least important.","zh":"从最重要到最不重要，依次点选。"},"options":[{"value":"Speed","label":{"en":"Speed","zh":"速度"}},{"value":"Polish","label":{"en":"Polish","zh":"精致程度"}},{"value":"Cost","label":{"en":"Cost","zh":"成本"}},{"value":"Flexibility","label":{"en":"Flexibility","zh":"灵活性"}}]},{"id":"feelings","type":"matrix","title":{"en":"How true are these of your current product?","zh":"以下说法在多大程度上符合您现有的产品？"},"rows":[{"id":"clear","label":{"en":"It is clear","zh":"清晰易懂"}},{"id":"fast","label":{"en":"It is fast","zh":"速度快"}},{"id":"loved","label":{"en":"People love it","zh":"深受用户喜爱"}}],"columns":[{"value":"Not at all","label":{"en":"Not at all","zh":"完全不符合"}},{"value":"A little","label":{"en":"A little","zh":"略微符合"}},{"value":"Somewhat","label":{"en":"Somewhat","zh":"部分符合"}},{"value":"Mostly","label":{"en":"Mostly","zh":"基本符合"}},{"value":"Entirely","label":{"en":"Entirely","zh":"完全符合"}}]},{"id":"confidence","type":"rating","title":{"en":"How confident are you in the plan?","zh":"您对这个计划有多大信心？"}},{"id":"recommend","type":"scale","title":{"en":"How likely are you to recommend this to a friend?","zh":"您有多大可能把它推荐给朋友？"},"required":true,"labels":[{"en":"Not at all","zh":"完全不会"},{"en":"Certainly","zh":"一定会"}]},{"id":"brief","type":"file","title":{"en":"Is there a brief or a sketch you can share?","zh":"有可以提供的需求说明或草图吗？"},"body":{"en":"Drop files here, or choose them.","zh":"将文件拖到此处，或点击选择。"},"max":3,"maxSize":10,"accept":["pdf","png","jpg","jpeg","docx","pptx","md","csv","xml","html"]},{"id":"notes","type":"long","title":{"en":"Anything else we should know?","zh":"还有什么需要我们了解的吗？"},"placeholder":{"en":"Take all the room you need","zh":"想写多少都可以"}},{"id":"consent","type":"consent","title":{"en":"May we keep your answers on file?","zh":"我们可以留存您的回答吗？"},"body":{"en":"We use them only to prepare for our conversation.","zh":"仅用于为我们之后的沟通做准备。"},"label":{"en":"Yes, that is fine","zh":"可以，没问题"},"required":true}],"outro":{"title":{"en":"Thank you.","zh":"谢谢。"},"body":{"en":"We will be in touch shortly.","zh":"我们稍后会与您联系。"}}}', 'seed', '2026-11-26T00:00:00.000Z');
INSERT INTO questionnaires (slug, revision, created_at, updated_at) VALUES ('demo', 1, '2026-11-26T00:00:00.000Z', '2026-11-26T00:00:00.000Z');
INSERT INTO revisions (slug, revision, definition, imported_by, imported_at) VALUES ('onboarding', 1, '{"title":{"en":"Getting started","zh":"开始之前"},"languages":["en","zh"],"audience":"invite","questions":[{"id":"welcome","type":"statement","eyebrow":{"en":"For {{customer}}","zh":"致 {{customer}}"},"title":{"en":"A few questions before we begin.","zh":"开始之前，想先问您几个问题。"},"body":{"en":"This should take about five minutes. Your answers are saved as you go, so you can stop and return to this link at any time.","zh":"大约需要五分钟。您的回答会随时自动保存，可以中途离开，之后再通过此链接继续填写。"}},{"id":"contact","type":"text","title":{"en":"Who is our main point of contact at {{customer}}?","zh":"{{customer}} 的主要联系人是哪位？"},"required":true,"placeholder":{"en":"Full name","zh":"姓名"}},{"id":"email","type":"email","title":{"en":"What is the best email for them?","zh":"联系人常用的邮箱是？"},"required":true},{"id":"goal","type":"long","title":{"en":"What would make this project a success?","zh":"怎样才算这个项目成功？"},"body":{"en":"A sentence or two is plenty.","zh":"一两句话就够了。"},"required":true},{"id":"cadence","type":"choice","title":{"en":"How often would you like to hear from us?","zh":"您希望我们多久向您汇报一次？"},"required":true,"options":[{"value":"Every week","label":{"en":"Every week","zh":"每周"}},{"value":"Every two weeks","label":{"en":"Every two weeks","zh":"每两周"}},{"value":"At each milestone","label":{"en":"At each milestone","zh":"每个阶段节点"}}]},{"id":"channels","type":"multi","title":{"en":"How do you prefer to talk?","zh":"您更喜欢用哪种方式沟通？"},"options":[{"value":"Email","label":{"en":"Email","zh":"电子邮件"}},{"value":"Video call","label":{"en":"Video call","zh":"视频会议"}},{"value":"Slack","label":{"en":"Slack","zh":"Slack"}},{"value":"Phone","label":{"en":"Phone","zh":"电话"}}],"other":true},{"id":"deadline","type":"boolean","title":{"en":"Is there a date this has to be done by?","zh":"项目有必须完成的日期吗？"},"required":true},{"id":"deadline_date","type":"date","title":{"en":"When is it?","zh":"是哪一天？"},"required":true,"showIf":{"id":"deadline","equals":true}},{"id":"assets","type":"file","title":{"en":"Do you have a logo or brand guidelines to share?","zh":"有可以提供的标志或品牌规范吗？"},"max":5,"maxSize":20},{"id":"notes","type":"long","title":{"en":"Is there anything else we should know?","zh":"还有什么需要我们了解的吗？"}}],"submit":{"title":{"en":"That’s everything.","zh":"全部完成了。"},"body":{"en":"Swipe back to review, or send your answers to us now.","zh":"可以向右滑动检查回答，或现在提交给我们。"},"label":{"en":"Send","zh":"提交"}},"outro":{"title":{"en":"Thank you.","zh":"谢谢。"},"body":{"en":"We have everything we need from {{customer}} for now, and will be in touch shortly.","zh":"我们已收到 {{customer}} 的全部信息，稍后会与您联系。"}}}', 'seed', '2026-11-26T00:00:00.000Z');
INSERT INTO questionnaires (slug, revision, created_at, updated_at) VALUES ('onboarding', 1, '2026-11-26T00:00:00.000Z', '2026-11-26T00:00:00.000Z');
INSERT INTO revisions (slug, revision, definition, imported_by, imported_at) VALUES ('tile-website', 1, '{"title":{"en":"Your new website","zh":"您的新网站"},"languages":["en","zh"],"audience":"invite","questions":[{"id":"welcome","type":"statement","eyebrow":{"en":"For {{customer}}","zh":"致 {{customer}}"},"title":{"en":"A few questions about your new website.","zh":"关于您的新网站，想先问您几个问题。"},"body":{"en":"This takes about fifteen minutes. Rough answers are fine, and “not sure yet” is a good answer too. Your answers are saved as you go, so you can stop and come back to this link at any time.","zh":"大约需要十五分钟。回答不必精确，“还不确定”也完全可以。您的回答会随时自动保存，可以中途离开，之后再通过此链接继续填写。"}},{"id":"about_intro","type":"statement","eyebrow":{"en":"Your business","zh":"您的公司"},"title":{"en":"First, a little about you.","zh":"首先，简单介绍一下您的公司。"}},{"id":"contact","type":"text","title":{"en":"Who is our main point of contact?","zh":"我们的主要联系人是哪位？"},"required":true,"placeholder":{"en":"Full name","zh":"姓名"}},{"id":"email","type":"email","title":{"en":"What is the best email for them?","zh":"联系人常用的邮箱是？"},"required":true},{"id":"phone","type":"tel","title":{"en":"And a phone number?","zh":"电话号码呢？"}},{"id":"trading_name","type":"text","title":{"en":"What name should the website use for the business?","zh":"网站上应使用什么公司名称？"},"body":{"en":"Your trading name, if it differs from your company name.","zh":"如果经营名称与注册公司名称不同，请填写经营名称。"},"required":true},{"id":"customers","type":"multi","title":{"en":"Who buys from you?","zh":"您的客户主要是哪些人？"},"body":{"en":"Choose as many as apply.","zh":"可多选。"},"required":true,"other":true,"options":[{"value":"Homeowners and renovators","label":{"en":"Homeowners and renovators","zh":"业主和自住装修客户"}},{"value":"Builders","label":{"en":"Builders","zh":"建筑商"}},{"value":"Tilers and other trades","label":{"en":"Tilers and other trades","zh":"贴砖师傅和其他工种"}},{"value":"Architects and interior designers","label":{"en":"Architects and interior designers","zh":"建筑师和室内设计师"}},{"value":"Commercial projects","label":{"en":"Commercial projects","zh":"商业项目"}}]},{"id":"trade_pricing","type":"boolean","title":{"en":"Do trade customers get different prices or their own accounts?","zh":"行业客户（如建筑商、施工师傅）是否享有不同价格或专属账户？"}},{"id":"showroom","type":"choice","title":{"en":"Can customers visit you in person?","zh":"客户可以到店参观吗？"},"required":true,"options":[{"value":"Yes, we have a showroom","label":{"en":"Yes, we have a showroom","zh":"可以，我们有展厅"}},{"value":"Yes, at our warehouse","label":{"en":"Yes, at our warehouse","zh":"可以，在我们的仓库"}},{"value":"Not yet, but a showroom is planned","label":{"en":"Not yet, but a showroom is planned","zh":"暂时不行，但计划开设展厅"}},{"value":"No, we are online only","label":{"en":"No, we are online only","zh":"不可以，我们只在网上销售"}}]},{"id":"showroom_address","type":"text","title":{"en":"Where is it, and when is it open?","zh":"地址在哪里？营业时间是？"},"placeholder":{"en":"Address and opening hours","zh":"地址和营业时间"},"showIf":{"id":"showroom","in":["Yes, we have a showroom","Yes, at our warehouse","Not yet, but a showroom is planned"]}},{"id":"goals","type":"rank","title":{"en":"What should the website do for you?","zh":"您希望网站为您带来什么？"},"body":{"en":"Tap them from most to least important.","zh":"请按重要程度从高到低依次点选。"},"options":[{"value":"Sell online","label":{"en":"Sell online","zh":"在线销售"}},{"value":"Bring in quote requests","label":{"en":"Bring in quote requests","zh":"获得询价"}},{"value":"Bring people to the showroom","label":{"en":"Bring people to the showroom","zh":"吸引客户到展厅"}},{"value":"Send out samples","label":{"en":"Send out samples","zh":"寄送样品"}},{"value":"Win trade customers","label":{"en":"Win trade customers","zh":"争取行业客户"}},{"value":"Build the brand","label":{"en":"Build the brand","zh":"建立品牌"}}]},{"id":"inspiration","type":"long","title":{"en":"Which websites do you like, and why?","zh":"您喜欢哪些网站？为什么？"},"body":{"en":"Tile shops, competitors or anything else. Links are perfect.","zh":"瓷砖店、竞争对手或其他任何网站都可以，直接贴链接就好。"},"placeholder":{"en":"One per line","zh":"每行一个"}},{"id":"products_intro","type":"statement","eyebrow":{"en":"Your products","zh":"您的产品"},"title":{"en":"Now, what you sell.","zh":"接下来，说说您卖什么。"},"body":{"en":"This tells us the most about how big the site will be.","zh":"这部分最能帮助我们判断网站的规模。"}},{"id":"product_count","type":"choice","title":{"en":"Roughly how many tile designs will be on the site?","zh":"网站上大约会有多少款瓷砖？"},"body":{"en":"Count each design once, even if it comes in several sizes or colours.","zh":"同一款式即使有多种尺寸或颜色，也只算一款。"},"required":true,"options":[{"value":"Fewer than 50","label":{"en":"Fewer than 50","zh":"少于 50 款"}},{"value":"50 to 200","label":{"en":"50 to 200","zh":"50 到 200 款"}},{"value":"200 to 1,000","label":{"en":"200 to 1,000","zh":"200 到 1,000 款"}},{"value":"More than 1,000","label":{"en":"More than 1,000","zh":"超过 1,000 款"}},{"value":"Not sure yet","label":{"en":"Not sure yet","zh":"还不确定"}}]},{"id":"variants","type":"boolean","title":{"en":"Do most designs come in several sizes, finishes or colours?","zh":"大部分款式是否有多种尺寸、表面效果或颜色？"}},{"id":"other_products","type":"multi","title":{"en":"What else do you sell besides tiles?","zh":"除了瓷砖，您还卖什么？"},"other":true,"options":[{"value":"Grout and adhesive","label":{"en":"Grout and adhesive","zh":"填缝剂和瓷砖胶"}},{"value":"Trims and edging","label":{"en":"Trims and edging","zh":"收边条和阳角线"}},{"value":"Waterproofing","label":{"en":"Waterproofing","zh":"防水材料"}},{"value":"Tools","label":{"en":"Tools","zh":"工具"}},{"value":"Bathroomware and tapware","label":{"en":"Bathroomware and tapware","zh":"卫浴洁具和水龙头"}},{"value":"Stone and pavers","label":{"en":"Stone and pavers","zh":"石材和铺路砖"}},{"value":"Installation","label":{"en":"Installation","zh":"安装服务"}},{"value":"Nothing else","label":{"en":"Nothing else","zh":"没有其他产品"}}]},{"id":"data_source","type":"choice","title":{"en":"Where does your product information live today?","zh":"您的产品信息目前存放在哪里？"},"body":{"en":"Names, sizes, prices and so on.","zh":"例如名称、尺寸、价格等。"},"other":true,"options":[{"value":"Supplier spreadsheets or catalogues","label":{"en":"Supplier spreadsheets or catalogues","zh":"供应商的表格或产品目录"}},{"value":"Our own spreadsheet","label":{"en":"Our own spreadsheet","zh":"我们自己的表格"}},{"value":"An inventory or stock system","label":{"en":"An inventory or stock system","zh":"进销存或库存系统"}},{"value":"Xero, MYOB or other accounting software","label":{"en":"Xero, MYOB or other accounting software","zh":"Xero、MYOB 或其他会计软件"}},{"value":"Nowhere yet","label":{"en":"Nowhere yet","zh":"还没有整理"}}]},{"id":"data_files","type":"file","title":{"en":"Can you share a sample of your product list or a catalogue?","zh":"能否提供一份产品清单样本或产品目录？"},"body":{"en":"Anything that shows what information you have.","zh":"任何能体现您现有信息的文件都可以。"},"max":5,"maxSize":25,"accept":["pdf","xls","xlsx","csv","doc","docx","zip"]},{"id":"photos","type":"choice","title":{"en":"What photos do you have of your products?","zh":"您现有哪些产品照片？"},"options":[{"value":"Our own product and room photos","label":{"en":"Our own product and room photos","zh":"自己拍摄的产品照和实景照"}},{"value":"Our own product photos only","label":{"en":"Our own product photos only","zh":"只有自己拍摄的产品照"}},{"value":"Photos from our suppliers","label":{"en":"Photos from our suppliers","zh":"供应商提供的照片"}},{"value":"None yet; we will need photography","label":{"en":"None yet; we will need photography","zh":"还没有，需要安排拍摄"}}]},{"id":"specs","type":"multi","title":{"en":"What should each product page show?","zh":"每个产品页面应显示哪些信息？"},"body":{"en":"Choose as many as apply.","zh":"可多选。"},"other":true,"options":[{"value":"Size and thickness","label":{"en":"Size and thickness","zh":"尺寸和厚度"}},{"value":"Finish (matt, gloss, textured)","label":{"en":"Finish (matt, gloss, textured)","zh":"表面效果（哑光、亮光、纹理）"}},{"value":"Slip rating","label":{"en":"Slip rating","zh":"防滑等级"}},{"value":"Wear rating (PEI)","label":{"en":"Wear rating (PEI)","zh":"耐磨等级（PEI）"}},{"value":"Indoor or outdoor use","label":{"en":"Indoor or outdoor use","zh":"适用室内或室外"}},{"value":"Wall or floor use","label":{"en":"Wall or floor use","zh":"适用墙面或地面"}},{"value":"Price per square metre","label":{"en":"Price per square metre","zh":"每平方米价格"}},{"value":"Stock available","label":{"en":"Stock available","zh":"库存数量"}},{"value":"A spec sheet to download","label":{"en":"A spec sheet to download","zh":"可下载的规格表"}}]},{"id":"features_intro","type":"statement","eyebrow":{"en":"How it works","zh":"网站功能"},"title":{"en":"How customers will use the site.","zh":"客户会如何使用网站。"}},{"id":"sales","type":"choice","title":{"en":"How should customers buy?","zh":"客户应如何购买？"},"required":true,"options":[{"value":"checkout","label":{"en":"They pay online, at a checkout","zh":"在网上下单付款"}},{"value":"quote","label":{"en":"They ask for a quote, and we follow up","zh":"提交询价，由我们跟进"}},{"value":"both","label":{"en":"Some products online, the rest by quote","zh":"部分产品在线购买，其余询价"}},{"value":"browse","label":{"en":"They browse, then call or visit us","zh":"在网上浏览，再来电或到店"}},{"value":"unsure","label":{"en":"Not sure yet","zh":"还不确定"}}]},{"id":"delivery","type":"multi","title":{"en":"How will orders reach customers?","zh":"订单如何送到客户手中？"},"options":[{"value":"Our own delivery","label":{"en":"Our own delivery","zh":"我们自己配送"}},{"value":"A freight company","label":{"en":"A freight company","zh":"物流公司"}},{"value":"Click and collect","label":{"en":"Click and collect","zh":"网上下单，到店自提"}},{"value":"Not sure yet","label":{"en":"Not sure yet","zh":"还不确定"}}],"showIf":{"id":"sales","in":["checkout","both"]}},{"id":"delivery_area","type":"choice","title":{"en":"Where will you deliver?","zh":"配送范围是？"},"options":[{"value":"Sydney only","label":{"en":"Sydney only","zh":"仅限悉尼"}},{"value":"Across NSW","label":{"en":"Across NSW","zh":"新州全境"}},{"value":"Across Australia","label":{"en":"Across Australia","zh":"澳洲全境"}},{"value":"Not sure yet","label":{"en":"Not sure yet","zh":"还不确定"}}],"showIf":{"id":"sales","in":["checkout","both"]}},{"id":"live_stock","type":"boolean","title":{"en":"Should the site show how much stock you have?","zh":"网站是否需要显示库存数量？"},"body":{"en":"Kept up to date automatically, this usually means connecting to your stock system.","zh":"要让库存自动保持最新，通常需要与您的库存系统对接。"}},{"id":"features","type":"multi","title":{"en":"Which of these would you like?","zh":"您希望有以下哪些功能？"},"body":{"en":"Choose as many as apply.","zh":"可多选。"},"other":true,"options":[{"value":"A calculator for how many tiles to buy","label":{"en":"A calculator for how many tiles to buy","zh":"计算所需瓷砖数量的工具"}},{"value":"Ordering samples","label":{"en":"Ordering samples","zh":"在线订购样品"}},{"value":"A gallery of finished projects","label":{"en":"A gallery of finished projects","zh":"完工案例展示"}},{"value":"Seeing tiles in a photo of a room","label":{"en":"Seeing tiles in a photo of a room","zh":"在房间照片中预览瓷砖效果"}},{"value":"Booking a showroom visit","label":{"en":"Booking a showroom visit","zh":"预约参观展厅"}},{"value":"A login for trade customers","label":{"en":"A login for trade customers","zh":"行业客户登录"}},{"value":"Saving favourites to a list","label":{"en":"Saving favourites to a list","zh":"收藏心仪产品"}},{"value":"Chat (WhatsApp, WeChat or similar)","label":{"en":"Chat (WhatsApp, WeChat or similar)","zh":"在线聊天（WhatsApp、微信等）"}}]},{"id":"languages","type":"choice","title":{"en":"Which languages should the site be in?","zh":"网站需要哪些语言？"},"required":true,"other":true,"options":[{"value":"English only","label":{"en":"English only","zh":"仅英文"}},{"value":"English and Simplified Chinese","label":{"en":"English and Simplified Chinese","zh":"英文和简体中文"}},{"value":"English and Traditional Chinese","label":{"en":"English and Traditional Chinese","zh":"英文和繁体中文"}},{"value":"English and both kinds of Chinese","label":{"en":"English and both kinds of Chinese","zh":"英文、简体中文和繁体中文"}}]},{"id":"translation","type":"choice","title":{"en":"Who will translate the content?","zh":"内容由谁来翻译？"},"options":[{"value":"We will","label":{"en":"We will","zh":"我们自己来"}},{"value":"We would like you to arrange it","label":{"en":"We would like you to arrange it","zh":"希望由你们安排"}},{"value":"Not sure yet","label":{"en":"Not sure yet","zh":"还不确定"}}],"showIf":{"id":"lang